// Smoke tests against the real course data (public/courses.json, generated by `npm run data`).
import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { buildCatalog, courseStatus, type RawCourse } from './catalog';
import { formatReq } from './prereq';
import { findRoute } from './path';
import { buildGraph } from './graph';

const FILE = 'public/courses.json';

describe.skipIf(!existsSync(FILE))('real catalog data', () => {
  const cat = buildCatalog(JSON.parse(readFileSync(FILE, 'utf8')) as RawCourse[]);

  it('loads and parses every course', () => {
    expect(cat.list.length).toBeGreaterThan(6000);
    const withTree = cat.list.filter((c) => c.req).length;
    expect(withTree).toBeGreaterThan(3000);
  });

  it('parses well-known prerequisites correctly', () => {
    expect(formatReq(cat.courses.get('CSC373H1')!.req)).toBe('CSC263H1 OR CSC265H1 OR CSC263H5 OR CSCB63H3');
    expect(formatReq(cat.courses.get('CSC207H1')!.req)).toBe('CSC148H1 OR CSC148H5 OR CSCA48H3 OR CSC111H1');
  });

  it('finds the expected equivalents and none of the overlapping-but-different courses', () => {
    const eq = (c: string) => [...(cat.equivalents.get(c) ?? [])].sort();
    expect(eq('CSC263H1')).toEqual(['CSC263H5', 'CSCB63H3']);
    expect(eq('CSC148H1')).toEqual(['CSC148H5', 'CSCA48H3']);
    expect(eq('CSC108H1')).not.toContain('CSC111H1');
    expect(eq('MAT223H1')).not.toContain('MAT224H1');
    expect(eq('MAT135H1')).not.toContain('MAT130H1');
  });

  it('works out course status, including via equivalents', () => {
    expect(courseStatus(cat, 'CSC263H1', new Set(['CSC236H1', 'STA237H1']))).toBe('available');
    expect(courseStatus(cat, 'CSC263H1', new Set(['CSC236H1']))).toBe('locked');
    expect(courseStatus(cat, 'CSC207H1', new Set(['CSCA48H3']))).toBe('available');
    expect(courseStatus(cat, 'CSC148H1', new Set(['CSC148H5']))).toBe('equivalent');
  });

  it('routes CSC373H1 through St. George Arts & Science courses', () => {
    const r = findRoute(cat, 'CSC373H1', new Set());
    expect(r.possible).toBe(true);
    expect(r.steps.at(-1)).toEqual(['CSC373H1']);
    expect(r.before).toContain('CSC263H1');
    for (const c of r.before) {
      expect(c.endsWith('1')).toBe(true);
      expect(cat.courses.get(c)?.division).toBe(cat.courses.get('CSC373H1')!.division);
    }
  });

  it('uses what is already done', () => {
    const r = findRoute(cat, 'CSC373H1', new Set(['CSC236H1', 'STA237H1']));
    expect(r.steps).toEqual([['CSC263H1'], ['CSC373H1']]);
  });
});

describe.skipIf(!existsSync(FILE))('route highlighting on real data', () => {
  const cat = buildCatalog(JSON.parse(readFileSync(FILE, 'utf8')) as RawCourse[]);
  const opts = { depth: 2, otherCampuses: false, showUnlocks: true, unlockOverrides: new Map(), expanded: new Set<string>(), collapsed: new Set<string>() };

  // Regression: CSC384H1's route uses MAT148H1 + MAT149H1 for STA237H1 through a nested
  // "all of" inside a "one of"; those arrows used to stay dark, leaving MAT149H1 disconnected.
  it('connects every link of the CSC384H1 route', () => {
    const done = new Set(['CSC110Y1', 'MAT148H1']);
    const route = findRoute(cat, 'CSC384H1', done);
    expect(route.links).toContainEqual(['MAT149H1', 'STA237H1']);
    const graph = buildGraph(cat, ['CSC384H1'], done, opts, route);
    const lit = graph.edges.filter((e) => e.animated);
    for (const [from, to] of route.links) {
      expect(lit.some((e) => e.source === from), `${from} has a lit arrow`).toBe(true);
      expect(lit.some((e) => e.target === to), `${to} has a lit arrow in`).toBe(true);
    }
  });
});
